args.new_string:
// AddInterval returns t moved forward by one billing interval: a month or a year. On a day the target month does not have,
// it is the month's last day. Times are UTC.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	return addMonths(t, intervalMonths(iv))
}

// Anchor is the start of a subscription's first paid period: its trial's end for a subscription that started with a trial,
// otherwise when it started. Every period of the subscription is counted from it.
func Anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return sub.TrialEnd.UTC()
	}
	return sub.StartedAt.UTC()
}

// PeriodStart returns the start of period n (n = 0, 1, 2, ...) of a plan that bills every iv, counted from anchor. Period n
// starts n intervals after the anchor, on the anchor's day of the month and at its time of day, or on the month's last day
// when the month is shorter. Each period is counted from the anchor, not from the period before, so a short month does not
// move the periods after it. Times are UTC.
func PeriodStart(anchor time.Time, iv store.Interval, n int) time.Time {
	return addMonths(anchor, n*intervalMonths(iv))
}

// PeriodNumber returns n such that PeriodStart(anchor, iv, n) is at t. t is expected to be a period boundary; for any other
// time it is the period that t falls in.
func PeriodNumber(anchor time.Time, iv store.Interval, t time.Time) int {
	a, b := anchor.UTC(), t.UTC()
	months := (b.Year()-a.Year())*12 + int(b.Month()-a.Month())
	return months / intervalMonths(iv)
}

func intervalMonths(iv store.Interval) int {
	if iv == store.Yearly {
		return 12
	}
	return 1
}

// addMonths returns t moved forward by months, on the same day of the month and at the same time of day when the target
// month has that day, and on the target month's last day when it does not. Times are UTC.
func addMonths(t time.Time, months int) time.Time {
	t = t.UTC()
	first := time.Date(t.Year(), t.Month()+time.Month(months), 1, t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), time.UTC)
	lastDay := time.Date(first.Year(), first.Month()+1, 0, 0, 0, 0, 0, time.UTC).Day()
	return time.Date(first.Year(), first.Month(), min(t.Day(), lastDay), t.Hour(), t.Minute(), t.Second(), t.Nanosecond(), time.UTC)
}

