func TestPeriodStartStaysOnTheAnchorDay(t *testing.T) {
	anchor := time.Date(2026, time.January, 31, 10, 15, 0, 0, time.UTC)
	want := []time.Time{
		time.Date(2026, time.January, 31, 10, 15, 0, 0, time.UTC),
		time.Date(2026, time.February, 28, 10, 15, 0, 0, time.UTC),
		time.Date(2026, time.March, 31, 10, 15, 0, 0, time.UTC),
		time.Date(2026, time.April, 30, 10, 15, 0, 0, time.UTC),
		time.Date(2026, time.May, 31, 10, 15, 0, 0, time.UTC),
	}
	for n, w := range want {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("period %d starts %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartLeapDay(t *testing.T) {
	anchor := time.Date(2028, time.February, 29, 0, 0, 0, 0, time.UTC)
	for n, w := range map[int]time.Time{
		0: time.Date(2028, time.February, 29, 0, 0, 0, 0, time.UTC),
		1: time.Date(2029, time.February, 28, 0, 0, 0, 0, time.UTC),
		4: time.Date(2032, time.February, 29, 0, 0, 0, 0, time.UTC),
	} {
		if got := PeriodStart(anchor, store.Yearly, n); !got.Equal(w) {
			t.Errorf("yearly period %d starts %v, want %v", n, got, w)
		}
	}
}

func TestPeriodNumberInvertsPeriodStart(t *testing.T) {
	anchor := time.Date(2026, time.January, 31, 10, 0, 0, 0, time.UTC)
	for _, iv := range []store.Interval{store.Monthly, store.Yearly} {
		for n := 0; n < 30; n++ {
			if got := PeriodNumber(anchor, iv, PeriodStart(anchor, iv, n)); got != n {
				t.Errorf("%s: PeriodNumber of period %d = %d", iv, n, got)
			}
		}
	}
}

func TestAddIntervalClampsToMonthEnd(t *testing.T) {
	jan31 := time.Date(2026, time.January, 31, 9, 0, 0, 0, time.UTC)
	if got := AddInterval(jan31, store.Monthly); !got.Equal(time.Date(2026, time.February, 28, 9, 0, 0, 0, time.UTC)) {
		t.Errorf("AddInterval(Jan 31, month) = %v", got)
	}
}

func TestAnchorIsTrialEndWhenThereIsATrial(t *testing.T) {
	started := time.Date(2026, time.January, 17, 8, 0, 0, 0, time.UTC)
	trialEnd := time.Date(2026, time.January, 31, 8, 0, 0, 0, time.UTC)
	if got := Anchor(store.Subscription{StartedAt: started}); !got.Equal(started) {
		t.Errorf("without a trial, anchor = %v", got)
	}
	if got := Anchor(store.Subscription{StartedAt: started, TrialEnd: &trialEnd}); !got.Equal(trialEnd) {
		t.Errorf("with a trial, anchor = %v", got)
	}
}
